/// Where the names come from, for a `source` cell.
pub const SOURCE: &str = "Unicode CLDR 48, common/main/<locale>.xml, localeDisplayNames/territories \
     (approved and contributed values), release-48, read 2026-09-27, and for the twelve \
     locales of the most-spoken languages 2026-09-28 (cldr48-most-spoken)";

/// One locale's names for the [`REGIONS`].
#[derive(Debug, Clone, Copy)]
pub struct TerritoryNames {
    /// The BCP 47 tag, spelled as [`crate::data::LOCALES`] spells it.
    pub tag: &'static str,
    /// The names in [`REGIONS`] order, each followed by a line feed; an
    /// empty line where CLDR has no release-level name.
    names: &'static str,
}

impl TerritoryNames {
    /// The name of the region at `index` in [`REGIONS`], if the locale has
    /// one.
    #[must_use]
    pub fn name_at(&self, index: usize) -> Option<&'static str> {
        self.names
            .split('\n')
            .nth(index)
            .filter(|name| !name.is_empty())
    }

    /// The name of `region`, an ISO 3166-1 alpha-2 code in any case, if it
    /// is one of the [`REGIONS`] and the locale names it.
    #[must_use]
    pub fn name_of(&self, region: &str) -> Option<&'static str> {
        region_index(region).and_then(|index| self.name_at(index))
    }

    /// The `alt="short"` name of `region` in this table's locale — `香港`
    /// for `HK` under `ja`, where [`Self::name_of`] is `中華人民共和国香港特別行政区` —
    /// if CLDR gives one at a release level; see [`short_name`].
    #[must_use]
    pub fn short_name_of(&self, region: &str) -> Option<&'static str> {
        short_name(self.tag, region)
    }
}

/// A territory's name and the tag of the table that gave it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TerritoryName {
    /// What the locale calls the territory.
    pub name: &'static str,
    /// The tag of the table that answered: `de` for a request for `de-AT`.
    pub tag: &'static str,
}

/// The position of `region` in [`REGIONS`], matched without regard to
/// case.
#[must_use]
pub fn region_index(region: &str) -> Option<usize> {
    let [first, second] = <[u8; 2]>::try_from(region.as_bytes()).ok()?;
    let wanted = [first.to_ascii_uppercase(), second.to_ascii_uppercase()];
    REGIONS
        .binary_search_by(|code| code.as_bytes().cmp(&wanted[..]))
        .ok()
}

/// The table for a data tag, spelled as [`TerritoryNames::tag`] is.
#[must_use]
pub fn table(tag: &str) -> Option<&'static TerritoryNames> {
    TABLES.iter().find(|table| table.tag == tag)
}

/// What `locale` calls `region`, from the first table in its fallback
/// chain that names it; `None` when none does, the root locale included.
#[must_use]
pub fn territory_name(locale: &Locale, region: &str) -> Option<TerritoryName> {
    let index = region_index(region)?;
    locale.fallback().find_map(|candidate| {
        let rendered = candidate.rendered()?;
        TABLES
            .iter()
            .filter(|table| rendered.as_str() == table.tag)
            .find_map(|table| {
                table.name_at(index).map(|name| TerritoryName {
                    name,
                    tag: table.tag,
                })
            })
    })
}

/// The `alt="short"` name the table tagged `tag` gives `region`, an ISO
/// 3166-1 alpha-2 code in any case: `UK` for `GB` and `Hong Kong` for
/// `HK` under `en`, `香港` for `HK` under `ja`.
///
/// Only the table's own file answers: no fallback chain is walked, so
/// that the short name comes from the same locale as the plain one it
/// stands beside. `None` where CLDR 48 has no short value for the region
/// in that file at a release level — most regions, since CLDR shortens
/// only a few names — and also where the file's short value is the
/// inheritance marker `↑↑↑`, which asks for the value inherited from the
/// locale's parent and, the parent being root, resolves to the plain name
/// itself: there is no shorter name than the one [`TerritoryNames::name_of`]
/// already gives.
#[must_use]
pub fn short_name(tag: &str, region: &str) -> Option<&'static str> {
    let wanted = REGIONS.get(region_index(region)?)?;
    SHORT_TABLES
        .iter()
        .find(|table| table.tag == tag)?
        .names
        .iter()
        .find(|(code, _)| code == wanted)
        .map(|(_, name)| *name)
}

