#[cfg(test)]
mod tests {
    use super::*;
    use crate::data::LOCALES;

    fn locale(tag: &str) -> Locale {
        Locale::parse(tag).expect("a tag")
    }

    #[test]
    fn the_regions_are_sorted_codes_and_every_table_has_a_line_for_each() {
        assert_eq!(REGIONS.len(), 195);
        for pair in REGIONS.windows(2) {
            assert!(pair[0] < pair[1], "{} !< {}", pair[0], pair[1]);
        }
        assert!(
            REGIONS.iter().all(|code| {
                code.len() == 2 && code.bytes().all(|byte| byte.is_ascii_uppercase())
            })
        );
        for table in TABLES {
            assert_eq!(
                table.names.split('\n').count(),
                REGIONS.len() + 1,
                "{}",
                table.tag
            );
            assert!(table.names.ends_with('\n'), "{}", table.tag);
        }
    }

    #[test]
    fn every_table_is_a_carried_locale_in_tag_order() {
        for pair in TABLES.windows(2) {
            assert!(
                pair[0].tag < pair[1].tag,
                "{} !< {}",
                pair[0].tag,
                pair[1].tag
            );
        }
        for table in TABLES {
            assert!(
                LOCALES.iter().any(|data| data.tag == table.tag),
                "{} is not a locale hc-i18n carries",
                table.tag
            );
            assert!(
                (0..REGIONS.len()).any(|index| table.name_at(index).is_some()),
                "{} names nothing",
                table.tag
            );
        }
    }

    #[test]
    fn no_name_is_padded_and_no_table_names_two_regions_alike() {
        for table in TABLES {
            let mut seen = alloc::collections::BTreeMap::new();
            for (index, code) in REGIONS.iter().enumerate() {
                let Some(name) = table.name_at(index) else {
                    continue;
                };
                assert_eq!(name, name.trim(), "{} {code}", table.tag);
                assert!(!name.contains(['\t', '\r']), "{} {code}", table.tag);
                if let Some(other) = seen.insert(name, code) {
                    panic!("{}: {other} and {code} are both {name}", table.tag);
                }
            }
        }
    }

    /// CLDR 48 `ja.xml` and `de.xml`: `<territory type="JP">日本</territory>`
    /// and `<territory type="DE">Deutschland</territory>`.
    #[test]
    fn japanese_names_japan_and_german_names_germany() {
        assert_eq!(
            territory_name(&locale("ja"), "JP"),
            Some(TerritoryName {
                name: "日本",
                tag: "ja"
            })
        );
        assert_eq!(
            territory_name(&locale("de-AT"), "de"),
            Some(TerritoryName {
                name: "Deutschland",
                tag: "de"
            })
        );
        assert_eq!(
            territory_name(&locale("zh-TW"), "JP").map(|name| name.tag),
            Some("zh-Hant")
        );
        assert_eq!(
            territory_name(&locale("en"), "HK").map(|name| name.name),
            Some("Hong Kong SAR China")
        );
    }

    /// Kabyle's `HK` is unconfirmed in CLDR 48 `kab.xml`, and Tibetan names
    /// Japan (`ཉི་ཧོང་`, approved) but not France (unconfirmed): each is
    /// left unnamed, and the chain, which runs to root, finds nothing.
    /// CLDR 48 `ur.xml` `<territory type="PK">پاکستان`, `sw.xml` `TZ`
    /// Tanzania, `pa_Arab.xml`'s one name, PK پاکستان, and `pt_PT.xml`'s
    /// `BH` Barém where `pt.xml` has Barein and its `AZ` the marker, so
    /// `pt.xml`'s Azerbaijão.
    #[test]
    fn the_most_spoken_languages_name_their_countries() {
        let name = |tag: &str, region: &str| {
            territory_name(&locale(tag), region).map(|found| (found.name, found.tag))
        };
        assert_eq!(name("ur", "PK"), Some(("پاکستان", "ur")));
        assert_eq!(name("sw-KE", "TZ"), Some(("Tanzania", "sw")));
        assert_eq!(name("pa-PK", "PK"), Some(("پاکستان", "pa-Arab")));
        assert_eq!(name("pa-PK", "IN"), None);
        assert_eq!(name("pa", "IN"), Some(("ਭਾਰਤ", "pa-Guru")));
        assert_eq!(name("pt-PT", "BH"), Some(("Barém", "pt-PT")));
        assert_eq!(name("pt", "BH"), Some(("Barein", "pt")));
        assert_eq!(name("pt-PT", "AZ"), Some(("Azerbaijão", "pt")));
        assert_eq!(name("yue-HK", "HK").map(|found| found.1), Some("yue-Hant"));
        assert_eq!(name("yue-CN", "CN").map(|found| found.1), Some("yue-Hans"));
    }

    #[test]
    fn a_name_below_the_release_levels_is_left_out() {
        assert_eq!(territory_name(&locale("kab"), "HK"), None);
        assert_eq!(
            territory_name(&locale("kab"), "JP").map(|name| name.name),
            Some("Jappu")
        );
        assert_eq!(
            territory_name(&locale("bo"), "JP").map(|name| name.name),
            Some("ཉི་ཧོང་")
        );
        assert_eq!(territory_name(&locale("bo"), "FR"), None);
        assert!(table("cop").is_none());
        assert_eq!(territory_name(&locale("cop"), "EG"), None);
        assert_eq!(territory_name(&Locale::ROOT, "JP"), None);
    }

    /// CLDR 48 `en.xml`: `<territory type="HK" alt="short">Hong
    /// Kong</territory>` and `GB` `UK`; `ja.xml`: `HK` `香港`, `GB` `英国`;
    /// `zh.xml` writes `GB`'s short name as `↑↑↑`, and `kab.xml`'s are all
    /// unconfirmed.
    #[test]
    fn short_names_are_cldrs_alt_short_values() {
        let english = table("en").expect("English");
        assert_eq!(english.short_name_of("hk"), Some("Hong Kong"));
        assert_eq!(english.name_of("HK"), Some("Hong Kong SAR China"));
        assert_eq!(short_name("en", "GB"), Some("UK"));
        assert_eq!(short_name("en", "US"), Some("US"));
        assert_eq!(short_name("en", "JP"), None);
        assert_eq!(short_name("ja", "HK"), Some("香港"));
        assert_eq!(short_name("ja", "MO"), Some("マカオ"));
        assert_eq!(short_name("ja", "PS"), Some("パレスチナ"));
        assert_eq!(short_name("ko", "KR"), Some("한국"));
        assert_eq!(short_name("zh-Hans", "HK"), Some("香港"));
        assert_eq!(short_name("zh-Hans", "GB"), None, "the marker ↑↑↑");
        assert_eq!(short_name("zh-Hant", "MO"), Some("澳門"));
        assert_eq!(short_name("kab", "HK"), None, "unconfirmed");
        assert_eq!(short_name("en", "EU"), None);
        assert_eq!(short_name("en-GB", "HK"), None, "a data tag, not a chain");
    }

    #[test]
    fn every_short_table_is_a_table_in_tag_order_with_names() {
        for pair in SHORT_TABLES.windows(2) {
            assert!(
                pair[0].tag < pair[1].tag,
                "{} !< {}",
                pair[0].tag,
                pair[1].tag
            );
        }
        for short in SHORT_TABLES {
            let plain = table(short.tag).expect("a table of plain names");
            assert!(!short.names.is_empty(), "{}", short.tag);
            for (code, name) in short.names {
                assert!(plain.name_of(code).is_some(), "{} {code}", short.tag);
                assert_eq!(*name, name.trim(), "{} {code}", short.tag);
                assert!(!name.is_empty() && !name.contains(['\t', '\n', '\r', '↑']));
            }
        }
    }

    #[test]
    fn a_code_outside_the_regions_names_nothing() {
        assert_eq!(region_index("jp"), region_index("JP"));
        assert_eq!(region_index("EU"), None);
        assert_eq!(region_index("JPN"), None);
        assert_eq!(territory_name(&locale("en"), "EU"), None);
    }
}
